// OpenClawValidationKeyMover.cs
// Optional Unity New Input System validation helper generated by Unity AI Setup Assistant.
// Purpose: prove the OpenClaw input.newInputKeyPress path can drive a project-side
// MonoBehaviour that reads UnityEngine.InputSystem.Keyboard.current directly.
// This is NOT production gameplay code. Safe to delete after smoke testing.
//
// Requires the Unity New Input System package (com.unity.inputsystem).
// Independent of FPSController and any legacy Input.GetAxisRaw/Input.GetKey paths.
// test.driveCharacter remains the deterministic gateway-side setup validation;
// this script is for feature-level New Input System smoke testing only.

using UnityEngine;
#if ENABLE_INPUT_SYSTEM
using UnityEngine.InputSystem;
#endif

namespace OpenClawValidation
{
    /// <summary>
    /// Standalone Unity New Input System smoke-test target for OpenClaw.
    /// Reads Keyboard.current directly so input.newInputKeyPress can drive it
    /// without touching FPSController or any production gameplay code.
    /// Safe no-op when Keyboard.current is null (no keyboard device bound yet).
    /// </summary>
    public class OpenClawValidationKeyMover : MonoBehaviour
    {
        [Tooltip("Units per second for translation keys.")]
        public float moveSpeed = 2f;

        [Tooltip("Degrees per second for rotation keys.")]
        public float rotateSpeed = 90f;

        [Tooltip("Enable the alternate I/J/K/L movement and U/O rotation keys.")]
        public bool enableExtraKeys = true;

        private void Update()
        {
#if ENABLE_INPUT_SYSTEM
            var keyboard = Keyboard.current;
            if (keyboard == null)
            {
                // Safe no-op when no keyboard device is bound yet.
                return;
            }

            float moveX = 0f;
            float moveZ = 0f;
            float yaw = 0f;

            // Primary W/A/S/D translation.
            if (keyboard.wKey.isPressed) moveZ += 1f;
            if (keyboard.sKey.isPressed) moveZ -= 1f;
            if (keyboard.aKey.isPressed) moveX -= 1f;
            if (keyboard.dKey.isPressed) moveX += 1f;

            // Primary Q/E yaw rotation.
            if (keyboard.qKey.isPressed) yaw -= 1f;
            if (keyboard.eKey.isPressed) yaw += 1f;

            if (enableExtraKeys)
            {
                // Alternate I/J/K/L translation.
                if (keyboard.iKey.isPressed) moveZ += 1f;
                if (keyboard.kKey.isPressed) moveZ -= 1f;
                if (keyboard.jKey.isPressed) moveX -= 1f;
                if (keyboard.lKey.isPressed) moveX += 1f;

                // Alternate U/O yaw rotation.
                if (keyboard.uKey.isPressed) yaw -= 1f;
                if (keyboard.oKey.isPressed) yaw += 1f;
            }

            if (moveX != 0f || moveZ != 0f)
                {
                Vector3 translation = new Vector3(moveX, 0f, moveZ);
                if (translation.sqrMagnitude > 1f)
                {
                    translation.Normalize();
                }
                transform.position += translation * moveSpeed * Time.deltaTime;
            }

            if (yaw != 0f)
            {
                transform.Rotate(0f, yaw * rotateSpeed * Time.deltaTime, 0f, Space.Self);
            }
#endif
        }
    }
}
